package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen2Test {

    private Document doc;
    private Element parent;
    private Element child1;
    private Element child2;
    private Element child3;

    @Before
    public void setUp() {
        doc = Jsoup.parse("<div><p id='p1'></p><p id='p2'></p><p id='p3'></p></div>");
        parent = doc.select("div").first();
        child1 = doc.select("#p1").first();
        child2 = doc.select("#p2").first();
        child3 = doc.select("#p3").first();
    }

    @Test
    public void testPreviousElementSibling_FirstElement() {
        assertNull(child1.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_MiddleElement() {
        assertEquals(child1, child2.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_LastElement() {
        assertEquals(child2, child3.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_OnlyElement() {
        doc = Jsoup.parse("<div><p id='p1'></p></div>");
        parent = doc.select("div").first();
        child1 = doc.select("#p1").first();
        assertNull(child1.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_NoParent() {
        Element orphan = new Element("p", "", new Attributes());
        assertNull(orphan.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_NullParentChildren() {
        parent.children().clear();
        assertNull(child1.previousElementSibling());
    }

    @Test(expected = NullPointerException.class)
    public void testPreviousElementSibling_NullParent() {
        child1.parent(null);
        child1.previousElementSibling();
    }
}
